    //
    // option
    //     {
    //         "marketId": "20997",
    //         "symbol": "BTC-USDC-20260130-160000-P",
    //         "quoteAssetId": "5",
    //         "baseAssetId": "1",
    //         "quoteSymbol": "USDC",
    //         "baseSymbol": "BTC",
    //         "quotePrecision": "4",
    //         "basePrecision": "8",
    //         "pricePrecision": "4",
    //         "quantityPrecision": "8",
    //         "costPrecision": "4",
    //         "minQuantityLimit": "0.00050000",
    //         "maxQuantityLimit": "200.00000000",
