    //         "vwap": "1.00000000",
    //         "open": "1.00000000",
    //         "close": "1.00000000",
    //         "last": "1.00000000",
    //         "change": "1.00000000",
    //         "percentage": "1.00000000",
    //         "average": "1.00000000",
