  std::shared_future<std::any>
  safeDeterministicCall(std::any method, std::any symbol = std::any{},
                        std::any since = std::any{},
                        std::any limit = std::any{},
                        std::any timeframe = std::any{},
                        std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any maxRetries = std::any{};
                 std::any maxRetriesparamsVariable =
                     this->handleOptionAndParams(params, method,
                                                 std::string("maxRetries"), 3);
                 maxRetries = ::getValue(maxRetriesparamsVariable, 0);
                 params = ::getValue(maxRetriesparamsVariable, 1);
                 if (isTrue(
                         isTrue(
                             isTrue((!isEqual(method,
                                              std::string("fetchOHLCV")))) &&
                             isTrue((!isEqual(
                                 method,
                                 std::string("fetchFundingRateHistory"))))) &&
                         isTrue(
                             (!isEqual(method, std::string("fetchTrades")))))) {
                   throw NotSupported(toString(add(
                       add(add(this->id, std::string(" safeDeterministicCall() "
                                                     "does not support the ")),
                           method),
                       std::string(" method"))));
                 }
                 std::any errors = 0;
                 params = this->omit(params, std::string("until"));
                 // the exchange returns the most recent data, so we do not need
                 // to pass until into paginated calls the correct util value
                 // will be calculated inside of the method
                 while (isLessThanOrEqual(errors, maxRetries)) {
                   try {
                     if (isTrue(isEqual(method, std::string("fetchOHLCV")))) {
                       return awaitValue(this->fetchOHLCV(
                           symbol, timeframe, since, limit, params));
                     } else if (isTrue(isEqual(
                                    method,
                                    std::string("fetchFundingRateHistory")))) {
                       return awaitValue(this->fetchFundingRateHistory(
                           symbol, since, limit, params));
                     } else {
                       return awaitValue(
                           this->fetchTrades(symbol, since, limit, params));
                     }
                   } catch (const std::exception &e) {
                     if (isTrue(isInstanceOf<RateLimitExceeded>(e))) {
                       throw;
                     }
                     errors = add(errors, 1);
                     if (isTrue(isGreaterThan(errors, maxRetries))) {
                       throw;
                     }
                   }
                 }
                 return ccxt::list{};
               })
        .share();
  }

  /**
   * @method
   * @name bullish#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see
   * https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#get-/v1/markets/-symbol-/candle
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch (max 100)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest entry
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any maxLimit = 100;
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, maxLimit));
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("timeBucket"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                     {std::string("_pageSize"), maxLimit},
                 };
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("createdAtDatetime[lte]"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 std::any until = this->safeInteger(
                     request, std::string("createdAtDatetime[lte]"));
                 std::any duration = this->parseTimeframe(timeframe);
                 std::any maxDelta =
                     multiply(multiply(1000, duration), maxLimit);
                 std::any startTime = since;
                 // both of since and until are required
                 if (isTrue(isTrue(isEqual(startTime, std::any{})) &&
                            isTrue(isEqual(until, std::any{})))) {
                   until = this->milliseconds();
                   startTime = subtract(until, maxDelta);
                 } else if (isTrue(isEqual(startTime, std::any{}))) {
                   startTime = subtract(until, maxDelta);
                 } else if (isTrue(isEqual(until, std::any{}))) {
                   until = this->sum(startTime, maxDelta);
                 }
                 ::setValue(request, std::string("createdAtDatetime[gte]"),
                            this->iso8601(startTime));
                 ::setValue(request, std::string("createdAtDatetime[lte]"),
                            this->iso8601(until));
                 std::any response =
                     awaitValue(this->publicGetV1MarketsSymbolCandle(
                         this->extend(request, params)));
                 //
                 //     [
                 //         {
                 //             "open": "100846.7490",
                 //             "high": "100972.4001",
                 //             "low": "100840.8129",
                 //             "close": "100972.2602",
                 //             "volume": "30.56064890",
                 //             "createdAtTimestamp": "1746720540000",
                 //             "createdAtDatetime": "2025-05-08T16:09:00.000Z",
                 //             "publishedAtTimestamp": "1746720636007"
                 //         }, ...
                 //     ]
                 //
                 std::any ohlcvs = this->toArray(response);
                 return this->parseOHLCVs(ohlcvs, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    return ccxt::list{
        this->safeInteger(ohlcv, std::string("createdAtTimestamp")),
        this->safeNumber(ohlcv, std::string("open")),
        this->safeNumber(ohlcv, std::string("high")),
        this->safeNumber(ohlcv, std::string("low")),
        this->safeNumber(ohlcv, std::string("close")),
        this->safeNumber(ohlcv, std::string("volume"))};
  }

  /**
   * @method
   * @name bullish#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see
   * https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#get-/v1/history/markets/-symbol-/funding-rate
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] not sent to exchange api, exchange api always returns
   * the most recent data, only used to filter exchange response
   * @param {int} [limit] the maximum amount of funding rate structures to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<std::any> fetchFundingRateHistory(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any maxLimit = 100;
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingRateHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   params = this->handlePaginationParams(
                       std::string("fetchFundingRateHistory"), since, params);
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchFundingRateHistory"), symbol, since,
                       limit, params, maxLimit));
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("swap")),
                                     true))) {
                   throw BadRequest(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "supports swap markets only"))));
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("_pageSize"),
                              this->getClosestLimit(limit));
                 }
                 params = this->handleSinceAndUntil(
                     since, params, std::string("updatedAtDatetime[gte]"),
                     std::string("updatedAtDatetime[lte]"));
                 std::any response = awaitValue(
                     this->publicGetV1HistoryMarketsSymbolFundingRate(
                         this->extend(request, params)));
                 //
                 //     [
                 //         {
                 //             "fundingRate": "0.00125",
                 //             "updatedAtDatetime": "2025-05-18T09:06:04.074Z"
                 //         },
                 //         {
                 //             "fundingRate": "0.00125",
                 //             "updatedAtDatetime": "2025-05-18T08:59:59.033Z"
                 //         }, ...
                 //     ]
                 //
                 std::any rates = ccxt::list{};
                 std::any result = this->toArray(response);
                 for (std::any i = 0; isLessThan(i, getArrayLength(result));
                      postFixIncrement(i)) {
                   std::any entry = ::getValue(result, i);
                   std::any datetime = this->safeString(
                       entry, std::string("updatedAtDatetime"));
                   arrayPush(rates,
                             ccxt::dict{
                                 {std::string("info"), entry},
                                 {std::string("symbol"), symbol},
                                 {std::string("fundingRate"),
                                  this->safeNumber(entry,
                                                   std::string("fundingRate"))},
                                 {std::string("timestamp"),
                                  this->parse8601(datetime)},
                                 {std::string("datetime"), datetime},
                             });
                 }
                 std::any sorted =
                     this->sortBy(rates, std::string("timestamp"));
                 return this->filterBySymbolSinceLimit(
                     sorted, ::getValue(market, std::string("symbol")), since,
                     limit);
               })
        .share();
  }

  /**
   * @method
   * @name bullish#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see
   * https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#tag--orders
   * @see
   * https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#tag--history
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve (5,
   * 25, 50, 100, default is 25)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest order to fetch
   * @param {string} [params.tradingAccountId] the trading account id (mandatory
   * parameter)
   * @param {string} [params.orderId] the id of the order to fetch for
   * @param {string} [params.clientOrderId] the client id of the order to fetch
   * for
   * @param {string} [params.status] filter by order status, 'OPEN',
   * 'CANCELLED', 'CLOSED', 'REJECTED'
   * @param {bool} [params.paginate] default false, when true will automatically
   * paginate by calling this endpoint multiple times. See in the docs all the
   * [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrders(std::any symbol = std::any{}, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(promiseAll(
                     ccxt::list{this->loadMarkets(), this->handleToken()}));
                 std::any tradingAccountId =
                     awaitValue(this->loadAccount(params));
                 std::any paginate =
                     this->safeBool(params, std::string("paginate"), false);
                 if (isTrue(isEqual(paginate, true))) {
                   params = this->handlePaginationParams(
                       std::string("fetchOrders"), since, params);
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchOrders"), symbol, since, limit, params,
                       100));
                 }
                 std::any market = std::any{};
                 std::any request = ccxt::dict{
                     {std::string("tradingAccountId"), tradingAccountId},
                 };
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 params = this->handleSinceAndUntil(since, params);
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("_pageSize"),
                              this->getClosestLimit(limit));
                 }
                 std::any method = std::string("privateGetV2HistoryOrders");
                 std::any methodparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrders"), std::string("method"),
                     method);
                 method = ::getValue(methodparamsVariable, 0);
                 params = ::getValue(methodparamsVariable, 1);
                 std::any response = ccxt::list{};
                 if (isTrue(
                         isEqual(method, std::string("privateGetV2Orders")))) {
                   //
                   //     [
                   //         {
                   //             "clientOrderId": "187",
                   //             "orderId": "297735387747975681",
                   //             "symbol": "BTCUSDC",
                   //             "price": "1.00000000",
                   //             "averageFillPrice": "1.00000000",
                   //             "stopPrice": "1.00000000",
                   //             "allowBorrow": false,
                   //             "quantity": "1.00000000",
                   //             "quantityFilled": "1.00000000",
                   //             "quoteAmount": "1.00000000",
                   //             "baseFee": "0.00100000",
                   //             "quoteFee": "0.0010",
                   //             "borrowedBaseQuantity": "1.00000000",
                   //             "borrowedQuoteQuantity": "1.00000000",
                   //             "isLiquidation": false,
                   //             "side": "BUY",
                   //             "type": "LMT",
                   //             "timeInForce": "GTC",
                   //             "status": "OPEN",
                   //             "statusReason": "User cancelled",
                   //             "statusReasonCode": "1002",
                   //             "createdAtDatetime":
                   //             "2021-05-20T01:01:01.000Z",
                   //             "createdAtTimestamp": "1621490985000",
                   //         }
                   //     ]
                   //
                   response = awaitValue(
                       this->privateGetV2Orders(this->extend(request, params)));
                 } else if (isTrue(isEqual(
                                method,
                                std::string("privateGetV2HistoryOrders")))) {
                   response = awaitValue(this->privateGetV2HistoryOrders(
                       this->extend(request, params)));
                 } else {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" fetchOrders() method parameter must "
                                       "be either \"privateGetV2Orders\" or "
                                       "\"privateGetV2HistoryOrders\""))));
                 }
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

  virtual std::any handlePaginationParams(std::any method,
                                          std::any since = std::any{},
                                          std::any params = ccxt::dict{}) {
    std::any ninetyDays =
        multiply(multiply(multiply(multiply(90, 24), 60), 60), 1000);
    std::any now = this->milliseconds();
    std::any allowedSince = subtract(now, ninetyDays);
    if (isTrue(isTrue((!isEqual(since, std::any{}))) &&
               isTrue((isLessThan(since, allowedSince))))) {
      throw BadRequest(toString(add(
          add(add(this->id, std::string(" ")), method),
          std::string(
              "() only allows fetching entries up to 90 days in the past"))));
    }
    params = this->omit(params, std::string("paginate"));
    params = this->extend(params, ccxt::dict{
                                      {std::string("paginationDirection"),
                                       std::string("backward")},
                                  });
    std::any until = this->safeInteger(params, std::string("until"));
    if (isTrue(isEqual(until, std::any{}))) {
      params = this->extend(params, ccxt::dict{
                                        {std::string("until"), now},
                                    });
    }
    return params;
  }

  virtual std::any handleSinceAndUntil(
      std::any since = std::any{}, std::any params = ccxt::dict{},
      std::any sinceKey = std::string("createdAtDatetime[gte]"),
      std::any untilKey = std::string("createdAtDatetime[lte]")) {
    std::any until = this->safeInteger(params, std::string("until"));
    if (isTrue(isTrue((!isEqual(since, std::any{}))) ||
               isTrue((!isEqual(until, std::any{}))))) {
      std::any timeDelta =
          multiply(multiply(multiply(multiply(7, 24), 60), 60), 1000); // 7 days
      if (isTrue(isEqual(since, std::any{}))) {
        since = subtract(until, timeDelta);
        params = this->omit(params, std::string("until"));
      } else if (isTrue(isEqual(until, std::any{}))) {
        until = this->sum(since, timeDelta);
        std::any now = this->milliseconds();
        if (isTrue(isGreaterThan(until, now))) {
          until = now;
        }
      }
      std::any sinceDate = this->iso8601(since);
      std::any untilDate = this->iso8601(until);
      ::setValue(params, sinceKey, sinceDate);
      ::setValue(params, untilKey, untilDate);
    }
    return params;
  }

  virtual std::any getClosestLimit(std::any limit) {
    std::any pageSize = 5;
    if (isTrue(isTrue((isGreaterThan(limit, 5))) &&
               isTrue((isLessThan(limit, 26))))) {
      pageSize = 25;
    } else if (isTrue(isTrue((isGreaterThan(limit, 25))) &&
                      isTrue((isLessThan(limit, 51))))) {
      pageSize = 50;
    } else if (isTrue(isGreaterThan(limit, 50))) {
      pageSize = 100;
    }
    return pageSize;
  }

